!function(r){function i(i){for(var e,a,P=i[0],o=i[1],m=i[2],c=0,h=[];c<P.length;c++)a=P[c],Object.prototype.hasOwnProperty.call(p,a)&&p[a]&&h.push(p[a][0]),p[a]=0;for(e in o)Object.prototype.hasOwnProperty.call(o,e)&&(r[e]=o[e]);for(u&&u(i);h.length;)h.shift()();return n.push.apply(n,m||[]),t()}function t(){for(var r,i=0;i<n.length;i++){for(var t,a=n[i],P=!0,o=1;o<a.length;o++)t=a[o],0!==p[t]&&(P=!1);P&&(n.splice(i--,1),r=e(e.s=a[0]))}return r}function e(i){if(a[i])return a[i].exports;var t=a[i]={i:i,l:!1,exports:{}};return r[i].call(t.exports,t,t.exports,e),t.l=!0,t.exports}var a={},p={14:0},n=[];e.m=r,e.c=a,e.d=function(r,i,t){e.o(r,i)||Object.defineProperty(r,i,{enumerable:!0,get:t})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,i){if(1&i&&(r=e(r)),8&i)return r;if(4&i&&"object"==typeof r&&r&&r.__esModule)return r;var t=Object.create(null);if(e.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:r}),2&i&&"string"!=typeof r)for(var a in r)e.d(t,a,function(i){return r[i]}.bind(null,a));return t},e.n=function(r){var i=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(i,"a",i),i},e.o=function(r,i){return Object.prototype.hasOwnProperty.call(r,i)},e.p="";var P=window.webpackJsonp=window.webpackJsonp||[],o=P.push.bind(P);P.push=i,P=P.slice();for(var m=0;m<P.length;m++)i(P[m]);var u=o;n.push([72,0]),t()}({72:function(r,i,t){"use strict";t.r(i);var e=t(0);Object(e.a)("ru","army",t(73),t(1))},73:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"轻武器","link":"ru_army#ru_army_iw"}],"model":"PPSh-41型冲锋枪","description":"<h6>综述：</h6><p>PPSh-41型冲锋枪是苏军在二战中装备最多的制式武器，也是二战中苏军最优秀武器之一，它的携弹量是德军著名的MP-40冲锋枪的一倍有多，因此更为具有持续性火力，它不用准确瞄准，5秒钟即可将全部子弹射出，射出的弹雨可横扫几平方米区域范围内的敌军，威力令人震撼。在东线战场上，正是装备了大量PPSh-41型冲锋枪的苏军部队顽强阻击了德军的进攻，随后收复被德军侵占的领土，最后攻克德国首都柏林。</p><p>PPSh-41型冲锋枪在中国被称“波波莎”冲锋枪，它生产工艺简单、坚固耐用，不用进行过多维修和保养，在各种恶劣环境下都能正常使用，因此而闻名世界。苏联从1941年开始生产至1947年停产，此型枪共生产了600多万支。二战之后，不少国家的军队仍在使用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_iwPPSh41_10.jpg","description":"<h6>PPSh-41型冲锋枪</h6><p></p><p>基本技术数据：</p><p>枪口径：7.62毫米；</p><p>枪全长：843毫米，枪管长：269毫米；</p><p>枪重量：3.63公斤（装弹后为5.4公斤）；</p><p>子弹初速：488米/秒；</p><p>最大射速：1000发/分钟；</p><p>有效射程：150米；</p><p>弹容量：弹鼓71发，弹匣35发。</p>","caption":""}],"part2title":"战场上的PPSh-41型冲锋枪","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_iwPPSh41_20.jpg","description":"（图左）1942年，一名手持PPSh-41型冲锋枪的苏军第42步兵团士官。（图中）1944年，一名手持PPSh-41型冲锋枪的苏军第141近卫步兵团士官。（图右）1942年，一名手持PPSh-41型冲锋枪的苏军第1山地特种分队列兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_21.jpg","description":"（图左）1941年，一名手持PPSh-41型冲锋枪的苏军第365步兵团列兵。（图中）1945年，一名手持PPSh-41型冲锋枪的苏军第188近卫步兵团侦察兵。（图右）1942年，一名手持PPSh-41型冲锋枪的苏军第143海军步兵旅士兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_22.jpg","description":"（图左）1942年，一名手持PPSh-41型冲锋枪的苏军第257步兵师军官。（图中）1942年，一名手持PPSh-41型冲锋枪，守卫苏联塞瓦斯托波尔要塞的苏军第9海军步兵团侦察兵。（图右）1943年，一名手持PPSh-41型冲锋枪的苏军第45后卫步兵师中士。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_23.jpg","description":"（图左）二战苏联战场，一名手持PPSh-41型冲锋枪的苏联海军陆战队上士。（图中）1942年，一名手持PPSh-41型冲锋枪的苏联近卫步兵师列兵。（图右）1943年，一名手持PPSh-41型冲锋枪的苏军冲锋枪手。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_24.jpg","description":"（图左）二战苏联战场，一名手持PPSh-41型冲锋枪的苏军侦察老兵。（图右）二战苏联战场，一名手持PPSh-41型冲锋枪的苏军年轻冲锋枪手。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_25.jpg","description":"（图左）1942年，苏联战场斯大林格勒地区，一名穿着白色伪装服、手持PPSh-41型冲锋枪的苏军士兵正在树林中等待进攻的命令。（图右）1944年，东线苏联战场乌克兰文尼察市区内，苏联乌克兰第1方面军的一名士兵，穿着雨衣手持PPSh-41型冲锋枪在一座楼房废墟中站岗，其目光警惕地注视着前方。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_26.jpg","description":"二战东线苏联战场，三名手持PPSh-41型冲锋枪的苏军冲锋枪手合照。他们胸前挂着战斗勋章，脸上满是笑容，是典型的苏军步兵英雄形象。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_27.jpg","description":"1942年冬季，东线苏联战场斯大林格勒保卫战，一名苏军战士挥舞着PPSh-41型冲锋枪在刚收复的马马耶夫岗山顶高呼“乌拉”。在斯大林格勒保卫战中，苏军和德军在这一制高点上进行为期多天、激烈殊死的争夺战，山岗阵地反复易手，最后是各占一边。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_28.jpg","description":"1942年11月，东线苏联战场斯大林格勒保卫战，在城市废墟中与进攻德军作战的苏军士兵，此时，苏军步兵已大量装备PPSh-41型冲锋枪，这种近战利器，一开枪就横扫一大片，在斯大林格勒保卫战中立下了汗马功劳。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_29.jpg","description":"1941年12月，东线苏联战场莫斯科保卫战，正对德军进行反击的苏军部队，一名手持PPSh-41型冲锋枪的冲锋枪手正卧伏在苏军一辆轻型坦克的装甲上随坦克向德军阵地冲击。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_30.jpg","description":"1943年秋季，东线苏联战场，一名苏军士兵用PPSh-41型冲锋枪支援冲锋的步兵，枪手近前有一些德军士兵的尸体。这张照片可能是战地摄影师在战场上临时要求这位冲锋枪手摆拍的，因为PPSh-41型冲锋枪有效射程只有150米，是无法对前方冲锋的士兵作如此远距离火力支援的，或者这些德军士兵的尸体也不是在照片位置战死的，但照片却也真实反映了战场的残酷。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_31.jpg","description":"1941年～1942年冬天，东线苏联战场莫斯科保卫战，雪地中一群向苏军投降的德军士兵，一名手持PPSh-41型冲锋枪的冲锋枪手正警惕地注视着向他们走来的德军俘虏。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_32.jpg","description":"二战后期东线战场，两名苏军步兵用一辆击毁的德军军车作掩护，手持PPSh-41型冲锋枪向德军射击。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_33.jpg","description":"在1944年3月，东线苏联战场乌克兰东南部德涅斯特地区，一支苏军部队正跟随T-34坦克群向德军进攻；这支部队的士兵已全都装备了PPSh-41冲锋枪，用其密集的火力来压制德军。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_34.jpg","description":"二战东线苏联战场，两名装备PPSh-41冲锋枪的苏军摩托化步兵正在执行巡逻任务。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_35.jpg","description":"1944年夏天，东线苏联战场，白俄罗斯游击队配合反攻的苏军部队，在敌后不断破坏德国运输线和打击德军补给站。图为一群手持PPSh-41冲锋枪的游击队员在摧毁一个德军“物资中心”后的集体合照。此时已是二战后期，苏联敌后游击队正在不断壮大，其武器装备的质量与数量也已大大提高。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_36.jpg","description":"1941年冬季，东线苏联战场摩尔曼斯克地区，在雪地中坚守阵地的苏联北方舰队海军陆战队战士，一名配备PPSh-41冲锋枪的指挥员正观察前方敌情。","caption":""},{"image":"imgs/ru/army/ru_army_iwPPSh41_37.jpg","description":"绘画：二战东线苏联战场，苏军一个炮兵观察小组正在将敌方阵地情况进行发报，手持望远镜的苏军战士胸前的PPSh-41冲锋枪配备的是35发容弹量的弹匣。","caption":""}]}')}});